from pathlib import Path
import json,hashlib,urllib.request
m=Path('docs/resource-image-import.json');data=json.loads(m.read_text(encoding='utf-8'))
items=[(1,'https://images.unsplash.com/photo-1589113050289-1c654e7e305d?auto=format&fm=jpg&w=1000&q=80','Dylan Calluy','https://unsplash.com/photos/black-and-white-projector-on-white-table-WU4ek4KCyjw','https://unsplash.com/license'),(4,'https://images.unsplash.com/photo-1580493783887-8c874c534e93?auto=format&fm=jpg&w=1000&q=80','Zoran Borojevic','https://unsplash.com/photos/black-microphone-on-black-table-jFTZdPd5hyQ','https://unsplash.com/license'),(3,'https://images.pexels.com/photos/11872896/pexels-photo-11872896.jpeg?auto=compress&cs=tinysrgb&w=1000','Alexey Demidov','https://www.pexels.com/photo/digital-multimeter-on-wooden-table-11872896/','https://www.pexels.com/license/'),(6,'https://images.pexels.com/photos/6466143/pexels-photo-6466143.jpeg?auto=compress&cs=tinysrgb&w=1000','Sergei Starostin','https://www.pexels.com/photo/close-up-photo-of-ethernet-cables-on-network-switch-6466143/','https://www.pexels.com/license/'),(8,'https://images.pexels.com/photos/16313656/pexels-photo-16313656.jpeg?auto=compress&cs=tinysrgb&w=1000','Kawê Rodrigues','https://www.pexels.com/photo/man-using-wacom-tablet-and-stylus-on-desk-16313656/','https://www.pexels.com/license/')]
for id,url,author,source,license in items:
 print('Downloading',id,flush=True);blob=urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'}),timeout=35).read();target='/uploads/resources/'+hashlib.md5(blob).hexdigest()+'.jpg';Path('public'+target).write_bytes(blob);data=[i for i in data if not(i['table']=='equipment' and i['id']==id)];data.append(dict(table='equipment',id=id,path=target,author=author,source=source,license=license))
m.write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8');print('All 9 equipment images prepared')
